NODE_PATH=/usr/local/lib/node_modules node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// Get available flights
const flights = db.prepare(\"SELECT flight_id, origin, destination, departure_time, arrival_time, dates_json FROM flights WHERE source_skill='tau2Airline'\").all();
console.log('=== Available Flights ===');
console.log('Total flights:', flights.length);
flights.forEach(f => {
  const dates = JSON.parse(f.dates_json || '{}');
  const availDates = Object.entries(dates).filter(([d, info]) => info.status === 'available');
  if (availDates.length > 0) {
    console.log('\nFlight:', f.flight_id, '|', f.origin, '->', f.destination, '| Dep:', f.departure_time, '| Arr:', f.arrival_time);
    availDates.forEach(([date, info]) => {
      console.log('  Date:', date, '| Seats:', JSON.stringify(info.available_seats), '| Prices:', JSON.stringify(info.prices));
    });
  }
});
db.close();
"

